```c
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int u, v;
    int max;
} Edge;

int cmp_edge(const void *a, const void *b) {
    const Edge *e1 = (const Edge *)a;
    const Edge *e2 = (const Edge *)b;
    if (e1->max != e2->max) return e2->max - e1->max;
    return e2->u - e1->u;
}

int cmp_int_desc(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    return y - x;
}

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    int *U = (int *)malloc(M * sizeof(int));
    int *V = (int *)malloc(M * sizeof(int));
    int *deg = (int *)calloc(N + 1, sizeof(int));

    for (int i = 0; i < M; i++) {
        scanf("%d %d", &U[i], &V[i]);
        deg[U[i]]++;
        deg[V[i]]++;
    }

    int *offset = (int *)malloc((N + 2) * sizeof(int));
    offset[1] = 0;
    for (int i = 1; i <= N; i++) {
        offset[i + 1] = offset[i] + deg[i];
    }
    int total_deg = offset[N + 1];

    int *adj = (int *)malloc(total_deg * sizeof(int));
    int *cur = (int *)malloc((N + 1) * sizeof(int));
    for (int i = 1; i <= N; i++) cur[i] = offset[i];

    for (int i = 0; i < M; i++) {
        int a = U[i], b = V[i];
        adj[cur[a]++] = b;
        adj[cur[b]++] = a;
    }

    for (int i = 1; i <= N; i++) {
        if (deg[i] > 0) {
            qsort(adj + offset[i], deg[i], sizeof(int), cmp_int_desc);
        }
    }

    int E = 2 * M;
    Edge *edges = (Edge *)malloc(E * sizeof(Edge));
    for (int i = 0; i < M; i++) {
        int a = U[i], b = V[i];
        int mx = a > b ? a : b;
        edges[2*i].u = a;
        edges[2*i].v = b;
        edges[2*i].max = mx;
        edges[2*i+1].u = b;
        edges[2*i+1].v = a;
        edges[2*i+1].max = mx;
    }

    qsort(edges, E, sizeof(Edge), cmp_edge);

    int *bit = (int *)calloc(total_deg + 1, sizeof(int));
    int *ans = (int *)malloc((N + 1) * sizeof(int));
    for (int i = 1; i <= N; i++) ans[i] = 1;

    for (int i = 0; i < E; i++) {
        int u = edges[i].u;
        int v = edges[i].v;

        // Query v's tree for max over w > u
        int lo = 0, hi = deg[v];
        int *v_adj = adj + offset[v];
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (v_adj[mid] > u) lo = mid + 1;
            else hi = mid;
        }
        int pos = lo;

        int q = 0;
        if (pos > 0) {
            int idx = pos;
            int base = offset[v];
            while (idx > 0) {
                if (bit[base + idx] > q) q = bit[base + idx];
                idx -= idx & -idx;
            }
        }

        int g;
        if (q == 0) g = 2;
        else g = q + 1;

        if (g > ans[u]) ans[u] = g;

        // Update u's tree at position of v in u's list
        lo = 0; hi = deg[u];
        int *u_adj = adj + offset[u];
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (u_adj[mid] > v) lo = mid + 1;
            else hi = mid;
        }
        int pos_update = lo + 1;

        int idx = pos_update;
        int base = offset[u];
        while (idx <= deg[u]) {
            if (g > bit[base + idx]) bit[base + idx] = g;
            idx += idx & -idx;
        }
    }

    for (int i = 1; i <= N; i++) {
        if (i > 1) printf(" ");
        printf("%d", ans[i]);
    }
    printf("\n");

    free(U); free(V); free(deg); free(offset); free(adj); free(cur);
    free(edges); free(bit); free(ans);

    return 0;
}
